async (page) => {
 const ctx=page.context(); const log=[]; let n=6;
 for (let i=0;i<30;i++){
  const st = await page.evaluate(()=>{const vis=e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0};const labels=[...document.querySelectorAll('label')].filter(vis).map(l=>l.innerText.trim());const heads=[...document.querySelectorAll('h1,h2,h3')].filter(vis).map(h=>h.innerText.trim()).join(' | ');const pii=[...document.querySelectorAll('input')].filter(vis).some(i=>['email','tel','date','password'].includes(i.type)||/name|email|phone|birth|dob|password/i.test((i.name||'')+(i.id||'')+(i.placeholder||'')));const radios=[...document.querySelectorAll('input[type=radio]')].filter(vis).length;return {labels,heads,pii,radios,url:location.pathname};});
  if (st.pii) { log.push({stop:'PII',st}); break; }
  if (!st.url.includes('/assessment/') || st.radios===0) { log.push({stop:'not a radio question',st}); break; }
  let pick=null; const risky=/harm|dead|suicid|kill|hurt yourself/i.test(st.heads);
  const pref = risky? ['Not at all','No','Never'] : ['Several days','Not at all','No','Never','Sometimes'];
  for (const p of pref) if (st.labels.includes(p)) { pick=p; break; }
  if (!pick) { log.push({stop:'no preferred option',st}); break; }
  if (i>0) { n++; await ctx.__cap(page,'Brightside',String(n).padStart(2,'0')+' - Assessment q'+(i+1)); }
  log.push({n, q:st.heads.slice(0,120), pick, opts:st.labels.length});
  await page.getByText(pick,{exact:true}).first().click(); await page.waitForTimeout(2500);
  const btn = page.getByRole('button',{name:/^(next|continue)$/i}); if (await btn.count() && await btn.last().isEnabled().catch(()=>false) && await page.locator('input[type=radio]').count()) { /* auto-advance check */ }
 }
 return log;
}

