import os,re
names={6:'PHQ-9 q1',7:'PHQ-9 q2',8:'PHQ-9 q3',9:'PHQ-9 q4',10:'PHQ-9 q5',11:'PHQ-9 q6',12:'PHQ-9 q7',13:'PHQ-9 q8',14:'PHQ-9 q9',15:'Difficulty follow-up',16:'GAD-7 q1',17:'GAD-7 q2',18:'GAD-7 q3',19:'GAD-7 q4',20:'GAD-7 q5',21:'GAD-7 q6',22:'GAD-7 q7',23:'Tried treatment before',24:'Suicide attempt history (answered No)'}
for f in sorted(os.listdir('.')):
    m=re.match(r'(\d\d) - Assessment( q\d)? \((desktop|mobile)(, full page)?\)\.png$',f)
    if m and int(m.group(1)) in names:
        new=f"{m.group(1)} - Assessment, {names[int(m.group(1))]} ({m.group(3)}{m.group(4) or ''}).png"
        if not os.path.exists(new): os.rename(f,new)
print('\n'.join(sorted(os.listdir('.'))[14:20]))
EOF

