   out[k]=await page.evaluate(()=>{const se=document.scrollingElement;let inner=0;for(const e of document.querySelectorAll('*')){const s=getComputedStyle(e);if(/(auto|scroll)/.test(s.overflowY)&&e.clientHeight>200&&e.scrollHeight>e.clientHeight+8)inner=Math.max(inner,e.scrollHeight-e.clientHeight);}return {docH:se.scrollHeight,vh:innerHeight,overflowPx:Math.max(0,se.scrollHeight-innerHeight),innerScrollPx:inner};});
   if(out[k].overflowPx>8){ const H=Math.min(out[k].docH,5000); try{ await page.screenshot({path:dir+name+' ('+k+', full page'+(out[k].docH>5000?', first 5000px':'')+').png',fullPage:true,clip:{x:0,y:0,width:w,height:H}}); }catch(e){ out[k].fullErr=String(e).slice(0,80);} }
  }
