async (page) => {
 const c=page.context(); const log=[]; let n=5;
 const pref=['Myself','Medication','Psychiatr','Anxiety','Several days','Somewhat','No preference','Not sure',"I'm not sure",'Virtual','Video','Online','No','Skip'];
 for(let i=0;i<12;i++){
  const st=await page.evaluate(()=>{const vis=e=>{const r=e.getBoundingClientRect();return r.width>0&&r.height>0};const btns=[...document.querySelectorAll('button,[role=button],[role=radio],[role=checkbox],label')].filter(vis).map(b=>b.innerText.trim()).filter(Boolean);const pii=[...document.querySelectorAll('input')].filter(vis).some(i=>['email','tel','date','password'].includes(i.type)||/name|email|phone|birth|dob|password/i.test((i.name||'')+(i.id||'')+(i.placeholder||'')+(i.getAttribute('aria-label')||'')));const h=[...document.querySelectorAll('h1,h2')].filter(vis).map(x=>x.innerText.trim()).join(' | ');const pr=[...document.querySelectorAll('[role=progressbar]')].map(e=>e.getAttribute('aria-valuenow')).join(',');return {btns,pii,h,pr,url:location.pathname}});
  if(i>0){ n++; await c.__cap(page,'Headway',String(n).padStart(2,'0')+' - Intake'); }
  if(st.pii){log.push({n,stop:'PII',st});break;}
  if(!st.url.includes('/intake/')){log.push({n,stop:'left intake',st});break;}
  let pick=null; for(const p of pref){const m=st.btns.find(b=>b===p||b.startsWith(p)); if(m){pick=m;break;}}
  log.push({n,h:st.h,pr:st.pr,opts:st.btns.slice(0,14),pick});
  if(!pick){break;}
  const before=page.url();
  await page.getByText(pick,{exact:true}).first().click({timeout:8000}); await page.waitForTimeout(2000);
  if(page.url()===before){ const cont=page.getByRole('button',{name:/^(Continue|Next)$/}); if(await cont.count()){ await cont.first().click({timeout:8000}).catch(()=>null); await page.waitForTimeout(2500);} }
 }
 return log;
}

